{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unrolled at the edge of the ruined city.",
      "visual_description": "On a windy hill above shattered spires, an ink-stained coat flutters as a brass compass spins; broken banners flap in the distance.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp warns of a trap before they enter.",
      "visual_description": "An oil lamp with a single glowing eye in its flame floats beside the mapmaker, casting amber light across her tired face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout is wound up for the mission.",
      "visual_description": "A small metal fox with blue glass eyes stands on a stone, its key-wind tail clicking as the cartographer turns it.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The rescuer arrives through a cracked windowpane.",
      "visual_description": "A figure in a clear diving helmet emerges from a shattered street window, his coat reflecting broken city lights in jagged shards.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers before the rusted castle gates.",
      "visual_description": "Four companions stand under a torn royal banner: the diver, the cartographer, the lamp's eye burning, and the tin fox at heel.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The fox scouts past an armored patrol.",
      "visual_description": "The clockwork fox slips along a cracked colonnade while dented metal helmets march past in the rain-slick street beyond.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "They find an official asleep at his post.",
      "visual_description": "A man slumps over a thick ledger pillow, stamped papers stuck to his sleeves, snoring beneath a cursed tower's long shadow.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The lamp refuses to enter the cursed tower.",
      "visual_description": "The oil lamp shrinks back, its flame-eye narrowed, as the diver peers up a spiral staircase choked in violet smoke.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a great winged beast pass overhead.",
      "visual_description": "A vast shadow with wide wings sweeps across a rooftop, and the cartographer pulls the fox into the shelter of a broken arch.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The diver slips through a tall mirror in the throne hall.",
      "visual_description": "A cracked floor-length mirror ripples like water as the helmeted rescuer dives in, his coat scattering reflected chandelier light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The lamp guides the cartographer through dark corridors.",
      "visual_description": "Amber light pools on mossy marble floors; the cartographer's compass spins wildly as the lamp hovers ahead, eye blinking.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door demands a password it will not accept.",
      "visual_description": "A heavy iron door etched with glowing runes pulses red; the tin fox paws at a keyhole shaped like a crescent moon.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Frightened faces watch from boarded windows.",
      "visual_description": "Pale eyes peer through cracks in shuttered houses as the cartographer presses a finger to her lips, the lamp dimmed to a whisper.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "They find the sleeping official again, blocking the way out.",
      "visual_description": "The ledger-pillowed man sprawls across a narrow stairway, papers fluttering as the diver carefully steps over his stamped sleeves.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The fox triggers an alarm of clattering bells.",
      "visual_description": "Tin paws skid on copper wires; lanterns swing wildly above as the cartographer scoops the fox up and bolts down a smoke-filled alley.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols close in along the riverside.",
      "visual_description": "Dented helmets and spear-tips bristle at both ends of a torchlit quay; the diver shields the lamp under his reflective coat.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The lamp shows the safe path across the cracked bridge.",
      "visual_description": "A long stone bridge sags over black water; the lamp's eye beams a thin gold line along stones that will hold their weight.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape past the city walls at dawn.",
      "visual_description": "Sunrise paints the ruined skyline pink behind four small figures on the far bridgehead, the cartographer's compass finally still.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    }
  ]
}

